CREATE TABLE IF NOT EXISTS tblMember2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, passwordHash VARCHAR(255) NOT NULL, fullName VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, address VARCHAR(255), birthDate DATE, email VARCHAR(100),
    role VARCHAR(20) NOT NULL, position VARCHAR(50), specialty VARCHAR(100), grade VARCHAR(50),
    CONSTRAINT member_profile CHECK (
        (role IN ('MANAGER','SALES_STAFF','WAREHOUSE_STAFF') AND position IS NOT NULL AND specialty IS NULL AND grade IS NULL)
        OR (role='TECHNICIAN' AND position IS NULL AND specialty IS NOT NULL AND grade IS NOT NULL)
    )
);
CREATE TABLE IF NOT EXISTS tblCustomer2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fullName VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL, address VARCHAR(255), email VARCHAR(100));
CREATE TABLE IF NOT EXISTS tblVehicle2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customerId BIGINT NOT NULL REFERENCES tblCustomer2(id), licensePlate VARCHAR(20) NOT NULL UNIQUE, brand VARCHAR(50), manufactureYear INTEGER, UNIQUE(customerId, id));
CREATE TABLE IF NOT EXISTS tblService2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT, category VARCHAR(80) NOT NULL, unitPrice NUMERIC(18,2) NOT NULL CHECK(unitPrice>=0), estimatedDuration INTEGER NOT NULL CHECK(estimatedDuration>0), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS tblSparePart2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT, category VARCHAR(80) NOT NULL, unit VARCHAR(20) NOT NULL, unitPrice NUMERIC(18,2) NOT NULL CHECK(unitPrice>=0), stockQuantity NUMERIC(12,3) NOT NULL DEFAULT 0 CHECK(stockQuantity>=0), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS tblSupplier2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, companyName VARCHAR(150) NOT NULL, address VARCHAR(255) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(100), taxCode VARCHAR(20), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS tblSupplierPart2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, supplierId BIGINT NOT NULL REFERENCES tblSupplier2(id), sparePartId BIGINT NOT NULL REFERENCES tblSparePart2(id), UNIQUE(supplierId,sparePartId));
CREATE TABLE IF NOT EXISTS tblServiceRequest2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, vehicleId BIGINT NOT NULL REFERENCES tblVehicle2(id), receivedById BIGINT NOT NULL REFERENCES tblMember2(id), receivedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, status VARCHAR(20) NOT NULL CHECK(status IN ('RECEIVED','IN_PROGRESS','COMPLETED','CANCELLED')));
CREATE TABLE IF NOT EXISTS tblServiceRequestDetail2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, requestId BIGINT NOT NULL REFERENCES tblServiceRequest2(id), serviceId BIGINT NOT NULL REFERENCES tblService2(id), technicianId BIGINT REFERENCES tblMember2(id), quantity INTEGER NOT NULL CHECK(quantity>0), unitPrice NUMERIC(18,2) NOT NULL CHECK(unitPrice>=0), status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','IN_PROGRESS','COMPLETED')), UNIQUE(requestId,serviceId));
CREATE TABLE IF NOT EXISTS tblRequestPartDetail2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, requestId BIGINT NOT NULL REFERENCES tblServiceRequest2(id), sparePartId BIGINT NOT NULL REFERENCES tblSparePart2(id), quantity NUMERIC(12,3) NOT NULL CHECK(quantity>0), unitPrice NUMERIC(18,2) NOT NULL CHECK(unitPrice>=0), UNIQUE(requestId,sparePartId));
CREATE TABLE IF NOT EXISTS tblInvoice2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(30) UNIQUE, serviceRequestId BIGINT NOT NULL UNIQUE REFERENCES tblServiceRequest2(id), createdById BIGINT NOT NULL REFERENCES tblMember2(id), issuedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, invoiceStatus VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(invoiceStatus IN ('DRAFT','CONFIRMED')), paymentStatus VARCHAR(20) NOT NULL DEFAULT 'UNPAID' CHECK(paymentStatus IN ('UNPAID','PAID')), paymentMethod VARCHAR(20), receivedAmount NUMERIC(18,2), paidAt TIMESTAMP, receivedById BIGINT REFERENCES tblMember2(id), CHECK(paymentStatus='UNPAID' OR (invoiceStatus='CONFIRMED' AND paymentMethod IS NOT NULL AND receivedAmount IS NOT NULL AND paidAt IS NOT NULL AND receivedById IS NOT NULL)));
CREATE TABLE IF NOT EXISTS tblInvoiceServiceDetail2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, invoiceId BIGINT NOT NULL REFERENCES tblInvoice2(id), serviceId BIGINT NOT NULL REFERENCES tblService2(id), quantity INTEGER NOT NULL CHECK(quantity>0), unitPrice NUMERIC(18,2) NOT NULL CHECK(unitPrice>=0), UNIQUE(invoiceId,serviceId));
CREATE TABLE IF NOT EXISTS tblInvoicePartDetail2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, invoiceId BIGINT NOT NULL REFERENCES tblInvoice2(id), sparePartId BIGINT NOT NULL REFERENCES tblSparePart2(id), quantity NUMERIC(12,3) NOT NULL CHECK(quantity>0), unitPrice NUMERIC(18,2) NOT NULL CHECK(unitPrice>=0), UNIQUE(invoiceId,sparePartId));
CREATE TABLE IF NOT EXISTS tblAppointment2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customerId BIGINT NOT NULL REFERENCES tblCustomer2(id), vehicleId BIGINT NOT NULL REFERENCES tblVehicle2(id), serviceId BIGINT NOT NULL REFERENCES tblService2(id), appointmentAt TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('BOOKED','CONFIRMED','CANCELLED','COMPLETED')), note TEXT, FOREIGN KEY (customerId, vehicleId) REFERENCES tblVehicle2(customerId, id));
CREATE TABLE IF NOT EXISTS tblImportOrder2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, supplierId BIGINT NOT NULL REFERENCES tblSupplier2(id), createdById BIGINT NOT NULL REFERENCES tblMember2(id), importedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, status VARCHAR(20) NOT NULL CHECK(status IN ('DRAFT','CONFIRMED')));
CREATE TABLE IF NOT EXISTS tblImportOrderDetail2 (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, importOrderId BIGINT NOT NULL REFERENCES tblImportOrder2(id), sparePartId BIGINT NOT NULL REFERENCES tblSparePart2(id), quantity NUMERIC(12,3) NOT NULL CHECK(quantity>0), importPrice NUMERIC(18,2) NOT NULL CHECK(importPrice>=0), UNIQUE(importOrderId,sparePartId));
CREATE INDEX IF NOT EXISTS idx_request_vehicle_status ON tblServiceRequest2(vehicleId,status);
CREATE INDEX IF NOT EXISTS idx_vehicle_customer ON tblVehicle2(customerId);
CREATE INDEX IF NOT EXISTS idx_service_name ON tblService2(name);
CREATE INDEX IF NOT EXISTS idx_part_name ON tblSparePart2(name);

-- Lock the profile while validating a staff reference in the writing transaction.
CREATE OR REPLACE FUNCTION check_member_role() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    member_id bigint := (to_jsonb(NEW) ->> TG_ARGV[0])::bigint;
BEGIN
    IF member_id IS NOT NULL THEN
        PERFORM id FROM tblMember2 WHERE id=member_id AND role=TG_ARGV[1] FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Member % must have role %', member_id, TG_ARGV[1] USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
CREATE OR REPLACE TRIGGER check_receivedById BEFORE INSERT OR UPDATE OF receivedById ON tblServiceRequest2
    FOR EACH ROW EXECUTE FUNCTION check_member_role('receivedbyid','SALES_STAFF');
CREATE OR REPLACE TRIGGER check_technicianId BEFORE INSERT OR UPDATE OF technicianId ON tblServiceRequestDetail2
    FOR EACH ROW EXECUTE FUNCTION check_member_role('technicianid','TECHNICIAN');
CREATE OR REPLACE TRIGGER check_createdById BEFORE INSERT OR UPDATE OF createdById ON tblInvoice2
    FOR EACH ROW EXECUTE FUNCTION check_member_role('createdbyid','SALES_STAFF');
CREATE OR REPLACE TRIGGER check_receivedById BEFORE INSERT OR UPDATE OF receivedById ON tblInvoice2
    FOR EACH ROW EXECUTE FUNCTION check_member_role('receivedbyid','SALES_STAFF');
CREATE OR REPLACE TRIGGER check_createdById BEFORE INSERT OR UPDATE OF createdById ON tblImportOrder2
    FOR EACH ROW EXECUTE FUNCTION check_member_role('createdbyid','WAREHOUSE_STAFF');

CREATE OR REPLACE FUNCTION preserve_referenced_role() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (SELECT FROM tblServiceRequest2 WHERE receivedById=OLD.id)
       OR EXISTS (SELECT FROM tblServiceRequestDetail2 WHERE technicianId=OLD.id)
       OR EXISTS (SELECT FROM tblInvoice2 WHERE createdById=OLD.id OR receivedById=OLD.id)
       OR EXISTS (SELECT FROM tblImportOrder2 WHERE createdById=OLD.id) THEN
        RAISE EXCEPTION 'Member % has records under role %', OLD.id, OLD.role USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;
CREATE OR REPLACE TRIGGER preserve_member_role BEFORE UPDATE OF role ON tblMember2
    FOR EACH ROW WHEN (NEW.role IS DISTINCT FROM OLD.role) EXECUTE FUNCTION preserve_referenced_role();
